from typing import Annotated, Any
from fastapi.dependencies.utils import get_dependant
from fastapi import Query
from pydantic import BeforeValidator, WithJsonSchema
import pytest

def test_invalid_query_param_type():
    FilterableStr = Annotated[
        str | dict,
        BeforeValidator(lambda x: x),
        WithJsonSchema({"type": "string"}, mode="serialization"),
    ]

    def endpoint(data: FilterableStr | None = Query(default=None)) -> Any:
        return data

    try:
        get_dependant(path="/hello", call=endpoint)
        print("Successfully called get_dependant without AssertionError")
    except AssertionError as e:
        print(f"Caught AssertionError: {e}")
        if str(e) == "Query param 'data' must be of one of the supported types":
            print("Correct error message received!")
        else:
            print(f"Incorrect error message: {e}")
            raise e

if __name__ == "__main__":
    try:
        test_invalid_query_param_type()
    except AssertionError as e:
        print(f"AssertionError: {e}")
        import sys
        sys.exit(1)

